#!/usr/bin/env node
/**
 * inject-links.js: Inject approved internal links into Shopify blog posts
 *
 * Reads approved-links.csv (generated by link-graph.js).
 * For each row where status = "approved":
 *   1. Fetches the source article's current body_html from Shopify
 *   2. Finds the suggested anchor text in the HTML
 *   3. Wraps it with <a href="target_url">anchor</a>
 *   4. Updates the article via Shopify API
 *   5. Marks the row as "done" in the CSV
 *
 * Usage:
 *   node src/inject-links.js                       # process approved-links.csv
 *   node src/inject-links.js --dry-run             # preview changes, don't write to Shopify
 *   node src/inject-links.js --file custom.csv     # use a different CSV file
 *   node src/inject-links.js --limit 10            # only process first 10 approved rows
 *
 * Safety:
 *   - Will NOT inject a link if the target URL already appears in the source HTML
 *   - Will NOT inject if the anchor text already has an <a> tag around it
 *   - Only touches the FIRST occurrence of the anchor text (most natural placement)
 *   - Backs up original HTML to inject-backup.json before any writes
 */

require('dotenv').config({ quiet: true });
const fs   = require('fs');
const path = require('path');

// ─── Config ──────────────────────────────────────────────────────────────────
const STORE     = process.env.SHOPIFY_STORE       || '';
const SITE      = (process.env.SITE_URL || '').replace(/\/+$/, '');
const OUTPUT_DIR = process.env.OUTPUT_DIR || path.resolve(__dirname, '..', 'output');
const TOKEN     = process.env.SHOPIFY_ADMIN_TOKEN;
const BLOG_ID   = process.env.SHOPIFY_BLOG_ID     || '';
const REST_BASE = `https://${STORE}/admin/api/2024-10`;

const args       = process.argv.slice(2);
const DRY_RUN    = args.includes('--dry-run');
const fileArg    = args.find(a => a.startsWith('--file'));
const CSV_FILE   = fileArg
  ? (fileArg.includes('=') ? fileArg.split('=')[1] : args[args.indexOf(fileArg)+1])
  : path.join(OUTPUT_DIR, 'approved-links.csv');
const limitArg   = args.find(a => a.startsWith('--limit'));
const LIMIT      = limitArg ? parseInt(limitArg.includes('=') ? limitArg.split('=')[1] : args[args.indexOf(limitArg)+1], 10) : 0;
const BACKUP_FILE = path.join(OUTPUT_DIR, 'inject-backup.json');

// ─── CSV helpers ─────────────────────────────────────────────────────────────
function parseCsv(text) {
  const lines  = text.trim().split('\n');
  const header = lines[0].split(',');
  return lines.slice(1).map(line => {
    // Handle quoted fields with commas inside
    const fields = [];
    let cur = '', inQ = false;
    for (let i = 0; i < line.length; i++) {
      if (line[i] === '"' && !inQ) { inQ = true; continue; }
      if (line[i] === '"' && inQ && line[i+1] === '"') { cur += '"'; i++; continue; }
      if (line[i] === '"' && inQ) { inQ = false; continue; }
      if (line[i] === ',' && !inQ) { fields.push(cur); cur = ''; continue; }
      cur += line[i];
    }
    fields.push(cur);
    const row = {};
    header.forEach((h, i) => row[h.trim()] = (fields[i] || '').trim());
    return row;
  });
}

function serializeCsv(rows) {
  if (rows.length === 0) return '';
  const header = Object.keys(rows[0]);
  const escape = v => (String(v).includes(',') || String(v).includes('"') || String(v).includes('\n'))
    ? `"${String(v).replace(/"/g, '""')}"` : String(v);
  return [
    header.join(','),
    ...rows.map(r => header.map(h => escape(r[h] ?? '')).join(','))
  ].join('\n');
}

// ─── Shopify helpers ─────────────────────────────────────────────────────────

/**
 * Detect whether a source URL is a product page or blog article.
 * Product pages use /products/, blog articles use /blogs/.
 */
function isProductUrl(url) {
  return url && url.includes('/products/');
}

async function getArticle(articleId) {
  const res = await fetch(
    `${REST_BASE}/blogs/${BLOG_ID}/articles/${articleId}.json?fields=id,title,body_html`,
    { headers: { 'X-Shopify-Access-Token': TOKEN } }
  );
  if (!res.ok) throw new Error(`GET article ${articleId}: ${res.status}`);
  const { article } = await res.json();
  return article;
}

async function getProduct(productId) {
  const res = await fetch(
    `${REST_BASE}/products/${productId}.json?fields=id,title,body_html`,
    { headers: { 'X-Shopify-Access-Token': TOKEN } }
  );
  if (!res.ok) throw new Error(`GET product ${productId}: ${res.status}`);
  const { product } = await res.json();
  return product;
}

async function updateArticle(articleId, bodyHtml) {
  const res = await fetch(
    `${REST_BASE}/blogs/${BLOG_ID}/articles/${articleId}.json`,
    {
      method: 'PUT',
      headers: {
        'X-Shopify-Access-Token': TOKEN,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ article: { id: articleId, body_html: bodyHtml } }),
    }
  );
  if (!res.ok) {
    const txt = await res.text();
    throw new Error(`PUT article ${articleId}: ${res.status}: ${txt.slice(0, 200)}`);
  }
  return res.json();
}

async function updateProduct(productId, bodyHtml) {
  const res = await fetch(
    `${REST_BASE}/products/${productId}.json`,
    {
      method: 'PUT',
      headers: {
        'X-Shopify-Access-Token': TOKEN,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ product: { id: productId, body_html: bodyHtml } }),
    }
  );
  if (!res.ok) {
    const txt = await res.text();
    throw new Error(`PUT product ${productId}: ${res.status}: ${txt.slice(0, 200)}`);
  }
  return res.json();
}

/**
 * Fetch content from either a blog article or product, based on source URL.
 * Returns { id, title, body_html, type: 'article'|'product' }
 */
async function getContent(id, sourceUrl) {
  if (isProductUrl(sourceUrl)) {
    const product = await getProduct(id);
    return { ...product, type: 'product' };
  }
  const article = await getArticle(id);
  return { ...article, type: 'article' };
}

/**
 * Update content for either a blog article or product.
 */
async function updateContent(id, bodyHtml, type) {
  if (type === 'product') return updateProduct(id, bodyHtml);
  return updateArticle(id, bodyHtml);
}

// ─── Link injection ───────────────────────────────────────────────────────────
/**
 * Inject a link into HTML.
 * Finds the first occurrence of `anchor` that is NOT already inside an <a> tag
 * and is NOT immediately adjacent to a link to `targetUrl`.
 * Wraps it: <a href="targetUrl">anchor</a>
 *
 * Returns { html, injected, reason } where injected=false means it was skipped.
 */
function injectLink(html, anchor, targetUrl) {
  // Safety check 1: link to this target already exists
  if (html.includes(`href="${targetUrl}"`) || html.includes(`href='${targetUrl}'`)) {
    return { html, injected: false, reason: 'already linked to target' };
  }

  // Safety check 2: anchor is empty or too short
  if (!anchor || anchor.length < 3) {
    return { html, injected: false, reason: 'anchor too short' };
  }

  // Case-insensitive search for the anchor text, but NOT inside an existing <a> tag
  // Strategy: split HTML into segments between <a>...</a> blocks, only touch non-link text
  const anchorLower = anchor.toLowerCase();

  // Parse out <a ...>...</a> blocks so we don't touch text inside links
  // We'll rebuild the HTML replacing only ONE occurrence outside of <a> tags
  const linkRe = /<a[\s>][\s\S]*?<\/a>/gi;
  const segments = [];
  let lastIdx = 0;
  let m;

  while ((m = linkRe.exec(html)) !== null) {
    segments.push({ type: 'text', content: html.slice(lastIdx, m.index) });
    segments.push({ type: 'link', content: m[0] });
    lastIdx = m.index + m[0].length;
  }
  segments.push({ type: 'text', content: html.slice(lastIdx) });

  // Find and replace the first occurrence in a text segment
  let replaced = false;
  const newSegments = segments.map(seg => {
    if (replaced || seg.type === 'link') return seg.content;

    const segLower = seg.content.toLowerCase();
    const pos = segLower.indexOf(anchorLower);
    if (pos === -1) return seg.content;

    // Get the actual casing from the source
    const actualAnchor = seg.content.slice(pos, pos + anchor.length);
    const before = seg.content.slice(0, pos);
    const after  = seg.content.slice(pos + anchor.length);

    replaced = true;
    return `${before}<a href="${targetUrl}">${actualAnchor}</a>${after}`;
  });

  if (!replaced) {
    return { html, injected: false, reason: `anchor "${anchor}" not found in article text` };
  }

  return { html: newSegments.join(''), injected: true, reason: 'ok' };
}

// ─── Backup ───────────────────────────────────────────────────────────────────
function loadBackup() {
  try { return JSON.parse(fs.readFileSync(BACKUP_FILE, 'utf8')); } catch { return {}; }
}

function saveBackup(backup) {
  fs.writeFileSync(BACKUP_FILE, JSON.stringify(backup, null, 2));
}

// ─── Main ─────────────────────────────────────────────────────────────────────
async function main() {
  console.log('\n💉  Link Injector\n');
  if (DRY_RUN) console.log('  ⚠️  DRY RUN: no changes will be written to Shopify\n');

  if (!TOKEN) { console.error('❌  SHOPIFY_ADMIN_TOKEN not set'); process.exit(1); }
  if (!BLOG_ID) { console.error('❌  SHOPIFY_BLOG_ID not set in .env'); process.exit(1); }
  if (!fs.existsSync(CSV_FILE)) {
    console.error(`❌  CSV not found: ${CSV_FILE}`);
    console.error('    Run node link-graph.js first to generate it.');
    process.exit(1);
  }

  // ── Read CSV ─────────────────────────────────────────────────
  const csvText = fs.readFileSync(CSV_FILE, 'utf8');
  const rows    = parseCsv(csvText);

  let approved = rows.filter(r => r.status === 'approved');
  if (LIMIT) approved = approved.slice(0, LIMIT);

  console.log(`  Found ${rows.length} total rows, ${approved.length} approved${LIMIT ? ` (limited to ${LIMIT})` : ''}\n`);

  if (approved.length === 0) {
    console.log('  Nothing to do: no rows with status="approved".');
    console.log('  Edit approved-links.csv: change "pending" → "approved" for links you want injected.\n');
    return;
  }

  // ── Load backup ──────────────────────────────────────────────
  const backup = loadBackup();

  // ── Process each approved row ────────────────────────────────
  let injected = 0, skipped = 0, errors = 0;

  for (const row of approved) {
    const { source_article_id, target_article_id, source_url, target_url,
            source_title, target_title, suggested_anchor } = row;

    const short = `"${source_title.slice(0,40)}" → "${target_title.slice(0,40)}"`;
    process.stdout.write(`  Processing ${short}...\n`);

    try {
      // Fetch current content (auto-detects article vs product from source_url)
      const content = await getContent(source_article_id, source_url);

      // Backup original if not already backed up
      if (!backup[source_article_id]) {
        backup[source_article_id] = {
          id:         source_article_id,
          type:       content.type,
          title:      content.title,
          body_html:  content.body_html,
          backedUpAt: new Date().toISOString(),
        };
        if (!DRY_RUN) saveBackup(backup);
      }

      // Inject link
      const result = injectLink(content.body_html, suggested_anchor, target_url);

      if (!result.injected) {
        console.log(`  ⏭️   Skipped: ${result.reason}`);
        row.status = `skipped: ${result.reason}`;
        skipped++;
        continue;
      }

      if (DRY_RUN) {
        console.log(`  ✅  [DRY RUN] Would inject (${content.type}): "${suggested_anchor}" → ${target_url}`);
        injected++;
        continue;
      }

      // Write to Shopify (uses correct API endpoint based on content type)
      await updateContent(source_article_id, result.html, content.type);
      console.log(`  ✅  Injected (${content.type}): "${suggested_anchor}" → ${target_url.replace(SITE,'')}`);

      row.status = `done:${new Date().toISOString().slice(0,10)}`;
      injected++;

      // Respectful rate limiting (Shopify: 2 req/s for REST): 1200ms to be safe
      await new Promise(r => setTimeout(r, 1200));

    } catch (e) {
      console.error(`  ❌  Error: ${e.message}`);
      row.status = `error: ${e.message.slice(0, 60)}`;
      errors++;
    }
  }

  // ── Update CSV with new statuses ─────────────────────────────
  if (!DRY_RUN) {
    fs.writeFileSync(CSV_FILE, serializeCsv(rows));
    console.log(`\n  📊  CSV updated with final statuses → ${CSV_FILE}`);
  }

  // ── Summary ──────────────────────────────────────────────────
  console.log('\n' + '─'.repeat(50));
  console.log(`  ✅  Injected:  ${injected}`);
  console.log(`  ⏭️   Skipped:   ${skipped}`);
  console.log(`  ❌  Errors:    ${errors}`);
  if (!DRY_RUN && injected > 0) {
    console.log(`\n  ⚠️   Backup of original HTML saved → ${BACKUP_FILE}`);
    console.log(`  Each entry holds the original body_html, keyed by article or product ID.`);
  }
  console.log('─'.repeat(50) + '\n');
}

if (require.main === module) {
  main().catch(e => {
    console.error('❌  Fatal:', e.message);
    process.exit(1);
  });
}

module.exports = { parseCsv, serializeCsv, injectLink, isProductUrl };
